-- City-specific preview stories for the four ordinary bonus-game tours.
-- Existing attempts retain their snapshots; gameplay and record rules stay unchanged.
with stories(skill_code, city_slug, preview_story) as (
  values
  ('speed', 'minsk', 'После Второй мировой войны Минск отстроили заново, с широкими проспектами и большими площадями. Выходи на местную арену и проверь свою скорость: забей нужные голы до конца отсчёта.'),
  ('speed', 'shanghai', 'На набережной Вайтань стоят старые здания, а через реку от них поднимаются небоскрёбы Пудуна. На шанхайской арене тебя ждёт матч на скорость. Начинай забивать с первых секунд, чтобы успеть выполнить цель.'),
  ('speed', 'sochi', 'В 2014 году Сочи принимал зимнюю Олимпиаду. Ледовые арены для неё построили у Чёрного моря. Сыграй в олимпийском городе и забей нужные голы, пока не закончится время.'),
  ('speed', 'tolyatti', 'Старую часть Тольятти перенесли из зоны затопления при строительстве водохранилища. Позже город вырос вместе с автозаводом. Сыграй матч на местной арене. Забей нужные голы до того, как таймер дойдёт до нуля.'),
  ('speed', 'moscow', 'Часы Спасской башни на Красной площади отбивают время уже несколько столетий. На московской арене следи за игровым таймером и успей забить нужные голы до конца матча.'),
  ('speed', 'nizhny-novgorod', 'В Нижнем Новгороде сходятся Волга и Ока. Над слиянием рек стоит старый кремль. Проверь свою скорость на местном льду: набери нужное число голов за отведённое время.'),
  ('speed', 'cherepovets', 'Череповец стоит на Шексне. Его рост связан с металлургическим комбинатом, который заработал в 1955 году. На местной арене сыграй матч на скорость и выполни цель до конца отсчёта.'),
  ('speed', 'yaroslavl', 'Ярославлю больше тысячи лет. Старый город с его храмами стоит на высоком берегу Волги. Сыграй здесь быстрый матч: начинай забивать сразу, чтобы успеть выполнить цель.'),
  ('speed', 'kazan', 'В Казанском кремле соседствуют мечеть Кул-Шариф и Благовещенский собор. Выходи на местную арену и проверь свою скорость. Забей нужные голы за отведённое время.'),
  ('speed', 'saint-petersburg', 'Летом в Петербурге наступают белые ночи. В светлых сумерках над Невой разводят мосты. Выходи на местный лёд и забивай без долгих пауз: цель нужно выполнить до конца отсчёта.'),
  ('accuracy', 'astana', 'Астана выросла в столицу посреди степи. Между её высотками гуляет ветер. На местной арене проверь точность своих бросков. Забей нужные шайбы с минимумом промахов.'),
  ('accuracy', 'nizhnekamsk', 'Нижнекамск строили в 1960-х вместе с большим нефтехимическим комплексом. Сыграй здесь матч на точность и выполни цель с минимумом промахов.'),
  ('accuracy', 'novosibirsk', 'Новосибирск появился во время строительства железнодорожного моста через Обь. Вокруг переправы вырос большой город. На местном льду выбирай момент для каждого броска и забей нужные шайбы с минимумом промахов.'),
  ('accuracy', 'vladivostok', 'Во Владивостоке улицы поднимаются на сопки, а мосты тянутся над морскими бухтами. На местной арене тебя ждёт проверка точности. Попади в ворота и постарайся обойтись без лишних промахов.'),
  ('accuracy', 'khabarovsk', 'Хабаровск стоит у слияния Амура и Уссури. С его набережной открывается вид на широкую реку. Сыграй здесь матч на точность. Забей нужные шайбы с минимумом промахов.'),
  ('accuracy', 'ufa', 'Уфа стоит у слияния рек Белой и Уфы. С высоких берегов открывается вид на речные долины. На местной арене добейся высокого процента попаданий и выполни цель матча.'),
  ('accuracy', 'yekaterinburg', 'Екатеринбург вырос вокруг железоделательного завода на Исети. Старая плотина сохранилась в центре города. Выходи на местный лёд и забей нужные шайбы, стараясь не промахиваться.'),
  ('accuracy', 'omsk', 'Омск начинался с крепости там, где Омь впадает в Иртыш. Сыграй матч на местной арене. Выбирай момент для броска, чтобы закончить игру с минимумом промахов.'),
  ('accuracy', 'chelyabinsk', 'Во время Второй мировой войны Челябинск выпускал танки. Тогда город получил прозвище Танкоград. Проверь точность на местной арене и выполни цель, не тратя шайбы на промахи.'),
  ('accuracy', 'magnitogorsk', 'Магнитогорск строили у горы Магнитной ради железной руды. Река Урал делит город между Европой и Азией. На местном льду сыграй матч на точность. Следи за воротами и старайся попадать каждым броском.'),
  ('marksmanship', 'toronto', 'В Торонто находится Зал хоккейной славы с трофеями и экспонатами об истории игры. На местной арене проверь свою меткость: забивай из сложных положений, чтобы набрать нужные очки.'),
  ('marksmanship', 'montreal', 'В Монреале в 1875 году сыграли первый организованный хоккейный матч в помещении. Он прошёл на катке «Виктория». Выходи на лёд в городе первого матча и проверь свою меткость: набери нужные очки за голы из сложных положений.'),
  ('marksmanship', 'boston', 'В Бостоне в 1773 году участники протеста выбросили в гавань груз чая. Это событие вошло в историю как Бостонское чаепитие. Сыграй здесь матч на меткость. Забивай из сложных положений, чтобы выполнить цель по очкам.'),
  ('marksmanship', 'new-york-metro', 'Нью-Йорк и его окрестности раскинулись у устья Гудзона. У воды поднимаются высотки Манхэттена. Сыграй здесь матч на меткость и набери очки за сложные голы.'),
  ('marksmanship', 'philadelphia', 'В Филадельфии приняли Декларацию независимости. Рядом с Индепенденс-холлом хранится Колокол Свободы. На местной арене проверь свою меткость: выбирай моменты для сложных бросков и набери нужные очки.'),
  ('marksmanship', 'washington', 'В Вашингтоне музеи и памятники тянутся вдоль Национальной аллеи. Над Капитолием возвышается белый купол. Сыграй матч на меткость на столичной арене. Здесь нужно забивать из сложных положений и набирать очки.'),
  ('marksmanship', 'pittsburgh', 'В Питтсбурге Аллегейни и Мононгахила сливаются в Огайо. Мосты соединяют кварталы на разных берегах. На местной арене сыграй матч на меткость и набери нужные очки за голы из сложных положений.'),
  ('marksmanship', 'detroit', 'Детройт вырос у реки на границе с Канадой. Позже автомобильные заводы сделали его одним из центров американского автопрома. Выходи на местный лёд и попробуй набрать нужные очки за сложные голы.'),
  ('marksmanship', 'chicago', 'После пожара 1871 года Чикаго отстроили заново. Сегодня в его центре стоят небоскрёбы. Сыграй на местной арене: выбирай сложные моменты для броска и набирай очки за голы.'),
  ('marksmanship', 'nashville', 'На Бродвее в Нэшвилле выступают музыкальные группы. В городе работает Зал славы кантри. На местной арене проверь свою меткость. Забивай из сложных положений и выполни цель по очкам.'),
  ('endurance', 'dallas', 'Даллас рос у железнодорожных путей на берегах реки Тринити. Железная дорога связала его с другими городами Техаса. Сыграй матч на местной арене. До финальной сирены забивай каждый следующий гол, пока не истекло время на него.'),
  ('endurance', 'denver', 'Денвер называют городом на высоте мили. Он стоит у восточного подножия Скалистых гор. На местной арене проверь выносливость. До конца матча забивай каждый следующий гол, пока его таймер не дошёл до нуля.'),
  ('endurance', 'salt-lake-city', 'В 2002 году Солт-Лейк-Сити принимал зимнюю Олимпиаду. Рядом с городом поднимаются горы Уосатч. Выходи на лёд в олимпийском городе и продержись до конца матча: забивай до того, как закончится время на очередной гол.'),
  ('endurance', 'winnipeg', 'Виннипег вырос у слияния Красной реки и Ассинибойна. В этом месте веками встречались торговцы. На местном льду выдержи весь матч, не давая таймеру до следующего гола дойти до нуля.'),
  ('endurance', 'edmonton', 'Через Эдмонтон течёт Северный Саскачеван. Вдоль его берегов тянутся городские парки. Сыграй здесь матч на выносливость. До финальной сирены забивай каждый следующий гол, пока его таймер не дошёл до нуля.'),
  ('endurance', 'calgary', 'Каждое лето в Калгари проходит Стампид, фестиваль с родео. На местной арене сыграй матч на выносливость. Продержись до конца игры, забивая до истечения времени на каждый следующий гол.'),
  ('endurance', 'vancouver', 'В Ванкувере рядом с морем поднимаются горы. Парк Стэнли занимает полуостров неподалёку от центра города. На местной арене сыграй матч на выносливость. До финальной сирены забивай до того, как закончится время на очередной гол.'),
  ('endurance', 'seattle', 'Космическую иглу в Сиэтле построили к Всемирной выставке 1962 года. Выходи на местную арену и проверь свою выносливость. Забивай до того, как закончится время на очередной гол, и продержись до сирены.'),
  ('endurance', 'los-angeles', 'Лос-Анджелес стоит на побережье Тихого океана. Здесь снимают кино и телевизионные сериалы. На местной арене сыграй матч на выносливость: до финальной сирены забивай каждый следующий гол, пока его таймер не дошёл до нуля.'),
  ('endurance', 'las-vegas', 'Лас-Вегас вырос среди пустыни Мохаве. По вечерам город зажигает огни. На местной арене продержись до конца матча. Каждый следующий гол нужно забить, пока его таймер не дошёл до нуля.')
)
update bonus_game game
   set preview_story = stories.preview_story,
       preview_revision = game.preview_revision + 1,
       revision = game.revision + 1,
       updated_at = now()
  from stories
 where game.slug = stories.skill_code || '-' || stories.city_slug
   and game.skill_code = stories.skill_code
   and game.status = 'active'
   and game.preview_story is distinct from stories.preview_story;
